import React, { useState } from 'react';

interface TextColorGuideProps {
  onBack: () => void;
  onHome: () => void;
}

// contrast 계산 함수 추가
function hexToRgb(hex: string) {
  const h = hex.replace('#', '');
  const bigint = parseInt(h, 16);
  if (h.length === 3) {
    return [
      ((bigint >> 8) & 0xf) * 17,
      ((bigint >> 4) & 0xf) * 17,
      (bigint & 0xf) * 17
    ];
  }
  return [
    (bigint >> 16) & 255,
    (bigint >> 8) & 255,
    bigint & 255
  ];
}
function luminance(r: number, g: number, b: number) {
  const a = [r, g, b].map(function (v) {
    v /= 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return a[0] * 0.2126 + a[1] * 0.7152 + a[2] * 0.0722;
}
function contrast(rgb1: number[], rgb2: number[]) {
  const lum1 = luminance(rgb1[0], rgb1[1], rgb1[2]);
  const lum2 = luminance(rgb2[0], rgb2[1], rgb2[2]);
  const brightest = Math.max(lum1, lum2);
  const darkest = Math.min(lum1, lum2);
  return (brightest + 0.05) / (darkest + 0.05);
}

const TextColorGuide: React.FC<TextColorGuideProps> = ({ onBack, onHome }) => {
  const [backgroundColor, setBackgroundColor] = useState('#f9f6f1');
  const [textColor, setTextColor] = useState('#222222');

  // 실시간 contrast 계산 및 추천
  const contrastRatio = contrast(hexToRgb(backgroundColor), hexToRgb(textColor));
  let recommendation = '';
  if (contrastRatio <= 2.15) {
    recommendation = '검정색(블랙) 사용 권장';
  } else {
    recommendation = '흰색(화이트)도 사용 가능';
  }

  const contrastExamples = [
    { bg: '#f9f6f1', text: '#222222', ratio: '4.5:1', recommendation: '검정색 사용 권장' },
    { bg: '#1e3a8a', text: '#ffffff', ratio: '12.6:1', recommendation: '흰색 사용 가능' },
    { bg: '#fce7f3', text: '#222222', ratio: '3.8:1', recommendation: '검정색 사용 권장' },
    { bg: '#000000', text: '#ffffff', ratio: '21:1', recommendation: '흰색 사용 가능' },
    { bg: '#ffffff', text: '#222222', ratio: '15.6:1', recommendation: '검정색 사용 가능' },
    { bg: '#f3f4f6', text: '#222222', ratio: '13.2:1', recommendation: '검정색 사용 가능' }
  ];

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 뒤로가기
          </button>
          <button className="btn-home" onClick={onHome}>
            🏠 홈
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            ⚫⚪ 텍스트 색상 고르기
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            어떤 배경 위에 어떤 텍스트 색을 써야 잘 보일지 알려드릴게요
          </h3>
          <div className="tip">
            <strong>1단계:</strong> 아래 사이트에서 텍스트 대비를 테스트해보세요<br/>
            <a href="https://snook.ca/technical/colour_contrast/colour.html#fg=FFFFFF,bg=FFE8DA" target="_blank" rel="noopener noreferrer" className="link">
              → 텍스트 대비 테스트 하는 사이트로 이동
            </a>
          </div>
          <div style={{ textAlign: 'center', margin: '24px 0 10px 0' }}>
            <img src="/images/whbl.png" alt="텍스트 대비 예시" style={{ maxWidth: '600px', width: '100%', borderRadius: '10px', boxShadow: '0 2px 8px #e0e7ef' }} />
            <div style={{ color: '#64748b', fontSize: '0.95rem', marginTop: '8px' }}>
              (텍스트 대비 테스트 예시 화면)
            </div>
          </div>
          <div className="tip">
            <strong>📐 기준 안내:</strong><br/>
            • <strong>폰트컬러(Foreground Colour), 배경컬러(Background Colour)를 입력하면 Contrast Ratio(대비 비율)가 계산됩니다.</strong><br/>
            • <strong>Contrast Ratio가 2.15 이하일 경우 → 검정색(블랙) 사용 권장</strong><br/>
            • <strong>2.15 이상일 경우 → 흰색(화이트)도 사용 가능</strong><br/>
            • WCAG 기준에 따라 NO/YES로 표시됩니다.
          </div>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            🎨 실시간 컬러 테스트
          </h3>

          <div className="grid">
            <div className="card">
              <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>배경색 선택</h4>
              <input 
                type="color" 
                value={backgroundColor}
                onChange={(e) => setBackgroundColor(e.target.value)}
                style={{ width: '100px', height: '50px', border: 'none', borderRadius: '8px' }}
              />
              <div className="color-code mt-20">{backgroundColor}</div>
            </div>

            <div className="card">
              <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>텍스트색 선택</h4>
              <div style={{ display: 'flex', gap: '16px', justifyContent: 'center', marginBottom: '10px' }}>
                <button
                  onClick={() => setTextColor('#222222')}
                  style={{
                    background: textColor === '#222222' ? '#222222' : '#f3f4f6',
                    color: textColor === '#222222' ? '#fff' : '#222',
                    border: textColor === '#222222' ? '2px solid #222' : '1px solid #e5e7eb',
                    borderRadius: '8px',
                    padding: '10px 22px',
                    fontWeight: 'bold',
                    fontSize: '1rem',
                    cursor: 'pointer',
                    transition: 'all 0.2s'
                  }}
                >
                  블랙
                </button>
                <button
                  onClick={() => setTextColor('#FFFFFF')}
                  style={{
                    background: textColor === '#FFFFFF' ? '#fff' : '#f3f4f6',
                    color: textColor === '#FFFFFF' ? '#222' : '#222',
                    border: textColor === '#FFFFFF' ? '2px solid #2563eb' : '1px solid #e5e7eb',
                    borderRadius: '8px',
                    padding: '10px 22px',
                    fontWeight: 'bold',
                    fontSize: '1rem',
                    cursor: 'pointer',
                    transition: 'all 0.2s'
                  }}
                >
                  화이트
                </button>
              </div>
              <div className="color-code mt-20">{textColor}</div>
            </div>
          </div>

          <div className="card mt-20" style={{ 
            backgroundColor: backgroundColor, 
            color: textColor,
            padding: '30px',
            textAlign: 'center',
            fontSize: '1.2rem',
            fontWeight: 'bold'
          }}>
            이렇게 보여집니다! 텍스트가 잘 보이나요?
            <div style={{ marginTop: '18px', fontSize: '1.25rem', fontWeight: 700, color: '#2563eb', letterSpacing: '0.5px', background: '#e0edff', borderRadius: '10px', padding: '10px 0', display: 'inline-block', minWidth: '180px' }}>
              Contrast Ratio: {contrastRatio.toFixed(2)}
            </div>
            <div style={{ marginTop: '8px', fontSize: '1.1rem', fontWeight: 500, color: '#2563eb' }}>
              추천: {recommendation}
            </div>
          </div>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            📊 대비 비율 예시
          </h3>

          <div className="grid">
            {contrastExamples.map((example, index) => (
              <div key={index} className="card" style={{ padding: '20px' }}>
                <div style={{ 
                  backgroundColor: example.bg, 
                  color: example.text,
                  padding: '15px',
                  borderRadius: '8px',
                  marginBottom: '10px',
                  textAlign: 'center',
                  fontWeight: 'bold'
                }}>
                  샘플 텍스트
                </div>
                <div style={{ fontSize: '0.9rem', color: '#64748b' }}>
                  <strong>대비 비율:</strong> {example.ratio}<br/>
                  <strong>추천:</strong> {example.recommendation}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="warning">
          <strong>⚠️ 수치 계산이 어렵거나 비교 예시가 필요하다면?</strong><br/>
          → <button className="btn">텍스트 대비 가이드 보기</button>
        </div>
      </div>
    </div>
  );
};

export default TextColorGuide;
